with post_processing.ScratchProject(PATH_TARGET_PROJECT, PATH_TARGET_PROJECT_PEN_PLUS) as project:
    project.register_extension('penP', 'https://extensions.turbowarp.org/obviousAlexC/penPlus.js')
    
    project.replace_custom_block_definition_script('model_renderer', 'TTF_Fill_Scanline_Triangle', TRI_FILLER_BLOCKS)

    asset_hash = project.add_asset(os.path.join(ROOT_DIR, 'src/models/texture.png'))
    target = project.get_target_by_name('model_renderer')
    target['costumes'].append({
        "name": "texture",
        "bitmapResolution": 1,
        "dataFormat": "png",
        "assetId": asset_hash,
        "md5ext": asset_hash + ".png",
        "rotationCenterX": 220,
        "rotationCenterY": 220
    })

